//! The window's string table (P3-files-app 2.2): generated by build.rs from strings/en.toml and strings/it.toml, read
//! with an explicit language (the window's UiLang), never through the process-wide state, so English and Italian
//! tests run side by side. The app's display name is not here: it is the kit's kit.app.files.

use oled_sys::i18n::S;
use oled_ui::node::Text;
use oled_ui::UiLang;

/// The generated table: `k` (one constant per key) and `TABLE`.
pub mod gen {
    include!(concat!(env!("OUT_DIR"), "/strings.rs"));
}
pub use gen::k;

/// The first private-use character: placeholders are parked on it while the pseudo-locale rewrites the text.
const PARK: u32 = 0xE000;

/// A key of this table in `lang`.
pub fn t(k: S, lang: UiLang) -> Text {
    lang.text(&gen::TABLE, k)
}

/// t() with each `{name}` placeholder replaced by its value in `args`; a placeholder without a value stays as written.
/// Under the pseudo-locale only the table's own words are rewritten, never the values.
pub fn tf(k: S, lang: UiLang, args: &[(&str, &str)]) -> Text {
    if args.is_empty() {
        return t(k, lang);
    }
    let template = gen::TABLE.get(k, lang.italian);
    let parked = park(template, args);
    let shown = if lang.pseudo { oled_ui::strings::pseudo(&parked) } else { parked };
    Text::Owned(unpark(&shown, args))
}

/// A label key of this table, or of the kit's when this table does not hold it (kit.new_tab, kit.verb.delete).
pub fn t_any(k: S, lang: UiLang) -> Text {
    if gen::TABLE.get(k, false).is_empty() {
        lang.kit(k)
    } else {
        t(k, lang)
    }
}

/// The template with every placeholder that has a value replaced by one private-use character (its index).
fn park(template: &str, args: &[(&str, &str)]) -> String {
    let mut out = String::with_capacity(template.len());
    let mut rest = template;
    while let Some(open) = rest.find('{') {
        out.push_str(&rest[..open]);
        let after = &rest[open + 1..];
        let name_len =
            after.find('}').filter(|&n| n > 0 && after[..n].bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_'));
        let slot = name_len.and_then(|n| args.iter().position(|(a, _)| *a == &after[..n]).map(|i| (n, i)));
        match slot.and_then(|(n, i)| char::from_u32(PARK + i as u32).map(|c| (n, c))) {
            Some((n, c)) => {
                out.push(c);
                rest = &after[n + 1..];
            }
            None => {
                out.push('{');
                rest = after;
            }
        }
    }
    out.push_str(rest);
    out
}

/// Every parked character replaced by its value.
fn unpark(parked: &str, args: &[(&str, &str)]) -> String {
    let mut out = String::with_capacity(parked.len() + args.iter().map(|(_, v)| v.len()).sum::<usize>());
    for c in parked.chars() {
        let slot = (c as u32).checked_sub(PARK).and_then(|i| args.get(i as usize));
        match slot {
            Some((_, v)) => out.push_str(v),
            None => out.push(c),
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn placeholders_are_filled_in_both_languages() {
        assert_eq!(tf(k::FILES_NAV_BACK_TO, UiLang::EN, &[("name", "docs")]), "Back to docs");
        assert_eq!(tf(k::FILES_NAV_BACK_TO, UiLang::IT, &[("name", "docs")]), "Torna a docs");
        assert_eq!(tf(k::FILES_STATUS_ITEMS_OTHER, UiLang::EN, &[("n", "1,204")]), "1,204 items");
        assert_eq!(tf(k::FILES_NAV_BACK_TO, UiLang::EN, &[]), "Back to {name}", "no value: as written");
        assert_eq!(tf(k::FILES_NAV_BACK_TO, UiLang::EN, &[("other", "x")]), "Back to {name}");
        assert_eq!(
            tf(k::FILES_NAV_BACK_TO, UiLang::EN, &[("name", "{name}")]),
            "Back to {name}",
            "values are not re-read"
        );
    }

    #[test]
    fn pseudo_keeps_values_and_rewrites_words() {
        let p = UiLang { italian: false, pseudo: true };
        let s = tf(k::FILES_NAV_BACK_TO, p, &[("name", "docs")]);
        assert!(s.starts_with('[') && s.contains("docs") && !s.contains("Back"), "{s}");
    }

    #[test]
    fn kit_labels_fall_back_to_the_kit_table() {
        assert_eq!(t_any(oled_ui::strings::k::KIT_NEW_TAB, UiLang::EN), "New tab");
        assert_eq!(t_any(k::FILES_NAV_BACK, UiLang::IT), "Indietro");
    }
}
